from __future__ import annotations

from typing import Any, Union

from taf.config.testline import Pdu as PduModel
from taf.internal.impact_radar import log_radar

from .available_devices import SupportedPduVendors
from .project_types import PDU_MODEL_TYPE, PDU_TYPE


class PduFactory(object):
    @staticmethod
    def _create(
        vendor: str, model=None, version: str | None = None, host: str | None = None, **kwargs: Any
    ) -> PDU_TYPE:
        pdu_vendor = SupportedPduVendors.get_vendor(vendor)
        pdu_model = pdu_vendor.get_model(model)
        pdu_device_type = pdu_model.get_versioned_model(version)

        log_radar(
            "Tracking the usage of PDU devices",
            vendor=vendor,
            model=model,
            version=version,
        )

        return pdu_device_type(host, **kwargs)

    @classmethod
    def create(cls, model: Union[str, PDU_MODEL_TYPE], host: str, **kwargs: Any) -> PDU_TYPE:
        """
        Creates PDU object.

        If model is a string, we assume that the `model` is really a `vendor`.
        User will get the DEFAULT PDU version of the DEFAULT PDU model
        of the given vendor.

        Otherwise the `model` is assumed to be a `taf.config.testline` PDU
        instance.
        User will get the specified PDU device.

        Raises DeviceNotSupported.
        """
        if not isinstance(model, str):
            base_pdu_attr = [field.name for field in list(PduModel.__attrs_attrs__)]
            child_pdu_attr = dict(filter(lambda x: x[0] not in base_pdu_attr, model.__dict__.items()))
            kwargs.update(child_pdu_attr)

            return cls._create(model.vendor, model.model, model.version, host, **kwargs)
        else:
            if vendor := kwargs.pop('vendor', None):
                return cls._create(vendor, model, host=host, **kwargs)
            return cls._create(model, host=host, **kwargs)
